package com.bemo.hr.product.risk;import jakarta.persistence.*;import lombok.Getter;import org.hibernate.annotations.TenantId;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="partner_risk_score_snapshots")@Getter public class PartnerRiskScoreSnapshot{@Id private String id;@TenantId@Column(name="app_id",nullable=false)private String appId;@Column(name="subject_type",nullable=false)private String subjectType;@Column(name="subject_id",nullable=false)private String subjectId;@Column(name="subject_name",nullable=false)private String subjectName;@Column(nullable=false)private int score;@Column(name="risk_band",nullable=false)private String riskBand;@Column(name="components_json",nullable=false,length=4000)private String componentsJson;@Column(name="operation_id",nullable=false)private String operationId;@Column(name="calculated_by",nullable=false)private String calculatedBy;@Column(name="calculated_at",nullable=false)private Instant calculatedAt;protected PartnerRiskScoreSnapshot(){}public PartnerRiskScoreSnapshot(String type,String subject,String name,int score,String band,String components,String operation,String actor){id=UUID.randomUUID().toString();subjectType=type;subjectId=subject;subjectName=name;this.score=score;riskBand=band;componentsJson=components;operationId=operation;calculatedBy=actor;calculatedAt=Instant.now();}}
